{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "The closest pterin analogue (biopterin) is administered peripherally and leads to CSF BH4, indicating that a more permeable oxidized precursor, rather than the tetrahydro form itself, is required to deliver BH4 to the CNS; this supports poor direct BBB penetration of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Guanosine enters the CNS via nucleoside transporters, but the query is a pterin lacking the ribose/nucleoside framework, so this transporter-mediated positive result has limited transferability and does not establish meaningful BH4 brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ara-G shows excellent CSF penetration as a nucleoside, but the query is not a nucleoside and the low structural similarity limits the relevance of this positive CNS penetration result.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "5-FormylTHF, a pterin-containing folate, is detected in brain after i.v. administration via transporter-mediated uptake, providing some support for active pterin transport; however, the query lacks the folate tail and is a different transporter substrate class.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is tetrahydrobiopterin (BH4), a highly polar, extensively hydrogen-bonded pterin with low passive permeability and likely efflux liability. The closest experimental evidence uses an oxidized pterin precursor to raise CSF BH4, implying the tetrahydro form itself is not the permeating species. Nucleoside and folate transporter evidence is structurally distant and does not override the known poor direct BBB penetration of BH4.",
  "evidence_gaps": [
    "No direct in vivo BBB/CSF measurement for the exact query (BH4) is provided.",
    "The closest pterin evidence (biopterin) is a precursor, not the tetrahydro form.",
    "No data on whether BH4 is a substrate for nucleoside transporters at the BBB in vivo.",
    "Human CNS exposure data for BH4 are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

